import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

public class Foo {
    private ThreadPoolTaskExecutor bad() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor(); //bad
        executor.setQueueCapacity(10);
        return executor;
    }

    private ThreadPoolTaskExecutor bad2() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor(); //bad, max not set
        executor.setCorePoolSize(10);
        return executor;
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

public class Foo {
    private ThreadPoolTaskExecutor good() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(10);
        executor.setMaxPoolSize(20);
        executor.setQueueCapacity(10);
        executor.initialize();
        return executor;
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

public class Foo {
    private final ThreadPoolTaskExecutor field = new ThreadPoolTaskExecutor(); //bad
    private ThreadPoolTaskExecutor other = new ThreadPoolTaskExecutor(); //bad
    private ThreadPoolTaskExecutor inCtor;

    public Foo() {
        inCtor = new ThreadPoolTaskExecutor(); //bad
        inCtor.setQueueCapacity(10);
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import javax.annotation.PostConstruct;

public class Foo {
    private final ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();

    @PostConstruct
    void init() {
        executor.setCorePoolSize(10);
        executor.setMaxPoolSize(20);
        executor.initialize();
    }
}

class Bar {
    private final ThreadPoolTaskExecutor executor;

    Bar() {
        executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(10);
        executor.setMaxPoolSize(20);
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

class MyExecutor extends ThreadPoolTaskExecutor {}

public class Foo {
    private MyExecutor bad() { return new MyExecutor(); } //bad
}

import org.springframework.boot.task.ThreadPoolTaskExecutorBuilder;
import org.springframework.boot.task.TaskExecutorBuilder;

public class Foo {
    Object bad() {
        return new ThreadPoolTaskExecutorBuilder().queueCapacity(10).build(); //bad
    }

    Object bad2() {
        return new TaskExecutorBuilder().threadNamePrefix("x").build(); //bad
    }

    Object bad3() {
        return new ThreadPoolTaskExecutorBuilder().corePoolSize(10).build(); //bad, max not set
    }
}

import org.springframework.boot.task.ThreadPoolTaskExecutorBuilder;

public class Foo {
    Object good() {
        return new ThreadPoolTaskExecutorBuilder().corePoolSize(10).maxPoolSize(20).queueCapacity(10).build();
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import org.springframework.boot.task.ThreadPoolTaskExecutorBuilder;

public class Foo {
    ThreadPoolTaskExecutor viaHelper() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        configure(executor);
        return executor;
    }

    ThreadPoolTaskExecutor viaTwoHelpers() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        configureCore(executor);
        configureMax(executor);
        return executor;
    }

    ThreadPoolTaskExecutor viaWrappedConstructorCall() {
        return configure(new ThreadPoolTaskExecutor());
    }

    Object builderViaHelper() {
        return sized(new ThreadPoolTaskExecutorBuilder()).build();
    }

    private ThreadPoolTaskExecutor configure(ThreadPoolTaskExecutor executor) {
        executor.setCorePoolSize(10);
        executor.setMaxPoolSize(20);
        return executor;
    }

    private void configureCore(ThreadPoolTaskExecutor executor) {
        executor.setCorePoolSize(10);
    }

    private void configureMax(ThreadPoolTaskExecutor executor) {
        executor.setMaxPoolSize(20);
    }

    private ThreadPoolTaskExecutorBuilder sized(ThreadPoolTaskExecutorBuilder builder) {
        return builder.corePoolSize(10).maxPoolSize(20);
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

public class Foo {
    private final ThreadPoolTaskExecutor executor;

    Foo() {
        executor = new ThreadPoolTaskExecutor();
        init();
    }

    private void init() {
        executor.setCorePoolSize(10);
        executor.setMaxPoolSize(20);
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

public class Foo {
    ThreadPoolTaskExecutor onlyCore() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor(); //bad, max not set by helper
        configureCore(executor);
        return executor;
    }

    ThreadPoolTaskExecutor unrelatedHelper() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor(); //bad, helper sets no sizes
        decorate(executor);
        return executor;
    }

    ThreadPoolTaskExecutor notCalled() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor(); //bad, configure is not called
        return executor;
    }

    private void configureCore(ThreadPoolTaskExecutor executor) {
        executor.setCorePoolSize(10);
    }

    private void decorate(ThreadPoolTaskExecutor executor) {
        executor.setThreadNamePrefix("x-");
    }

    private void configure(ThreadPoolTaskExecutor executor) {
        executor.setCorePoolSize(10);
        executor.setMaxPoolSize(20);
    }
}
